for(let i=0;i<moves.length;i++){const p=moves[i],color=i%2?"O":"X";if(p=="pass")continue;if(b[p]!=".")throw Error("occupied "+p);b[p]=color;let seen=new Set();for(const q of nb(p)){if(b[q]=="."||b[q]==color||seen.has(q))continue;let stack=[q],st=[],libs=new Set();seen.add(q);while(stack.length){let t=stack.pop();st.push(t);for(const v of nb(t)){if(b[v]==".")libs.add(v);else if(b[v]==b[q]&&!seen.has(v)){seen.add(v);stack.push(v)}}}if(!libs.size){captures[color]+=st.length;st.forEach(v=>b[v]=".");}}}
let final={};for(const l of load("board").split("\n")){let m=l.match(/^\s*([1-9])\s+([XO.](?:\s+[XO.]){8})\s+[1-9]/);if(m)m[2].split(/\s+/).forEach((v,i)=>final[cols[i]+m[1]]=v)}text({match:Object.keys(b).every(p=>b[p]==final[p]),captures,counts:Object.values(b).reduce((a,c)=>(a[c]=(a[c]||0)+1,a),{})});
store("sgf","(;GM[1]FF[4]SZ[9]KM[7]PB[KataGo 20k]PW[Codex]RE[W+20]"+moves.map((p,i)=>";"+(i%2?"W":"B")+"["+(p=="pass"?"":String.fromCharCode(97+cols.indexOf(p[0]))+String.fromCharCode(97+9-Number(p[1])))+"]").join("")+")\n");

